  ["2987a2c943a51d1d"] = { "Hazza'rah, il Tessitore di Sogni.\n\nSuo è il potere degli incubi, e possano i suoi nemici dormire per sempre.\n\nHazza'rah ora dimora lontano da qui. Un giorno, forse, tornerà...", "." },
  ["299362e20b1f2ac2"] = { "Potere! Potere glorioso!", "." },
