  ["299d16fb52eb1e02"] = { "Le razze del mondo periranno. È solo questione di tempo.", "." },
  ["29a44fc2d9b14b45"] = { "Se vuoi eccellere in cucina, fa' un salto alla Pig and Whistle Tavern nella Old Town e parla con Stephen Ryback. Quell'uomo sa cucinare un costolame come nessun altro.\n\nAccidenti... ora mi hai fatto venire fame delle sue famose costolette. Ma non contare che ti insegni quella ricetta!", "." },
  ["29aec30a8b362d05"] = { "Questa riga è quasi tutta un riempitivo...", "." },
  ["29af7090157b230b"] = { "Cosa rappresenti, spirito?", "." },
  ["29b2370eb77df793"] = { "iCoke - Descrizione (confezione regalo S.H.E.)", "." },
  ["29c34d00df543887"] = { "Oh cielo, mi hai colto di sorpresa! Felice di vederti, {name}: l'Azeroth Commerce Authority ha sempre bisogno di nuovi appaltatori.\r\n\nSe sei il tipo a cui piace passeggiare per la foresta raccogliendo materiali utili, o se hai le capacità per creare qualcosa da zero, be', qui ti sentirai proprio a casa!\r\n\nFammi sapere se hai domande.", "." },
  ["29cd7a2943d11720"] = { "Och, adoro una bella rissa, ma a volte il tuo nemico ha il cranio più spesso di uno scudo termico di torio. In quei casi ti serve un pizzico d'aiuto.", "." },
  ["29cdff81f5ad0961"] = { "Contaci!", "." },
  ["29d8a20ef6e35cfe"] = { "Userò bene il tempo, mio signore. Grazie.", "." },
  ["29db4ac3fde21f99"] = { "Mio fratello diceva che con questa rotta commerciale avremmo fatto un sacco di soldi, ma non mi aveva detto che toccava a me vivere da questa parte. Se ripassi di qui con lo zeppelin, potresti portarmi qualcosa da mangiare? A Orgrimmar vendono la carne migliore, e mi farebbe proprio comodo qualcosa che non sia morto settimane prima di smettere di muoversi.", "." },
  ["29f81c8ae83030ee"] = { "La leggenda narra che nei luoghi di conflitto estremo, in quelle che oggi sono note come ⟦Plaguelands=Terre Infette⟧, possano sgorgare dal terreno sorgenti pure e sacre. L'acqua di quelle sorgenti è stata chiamata '⟦Blood of Heroes=Sangue degli Eroi⟧' da artigiani e gente comune, in onore di coloro che caddero nella guerra contro il Flagello.", "." },
